import { createClient } from '@/lib/supabase/server'
import { PortalHeader, EmptyState, formatDate, StatusPill } from '@/components/portal/portal-shell'

export default async function PortalAnnouncementsPage() { const supabase = await createClient(); const { data } = await supabase.from('announcements').select('id,title,message,audience,publish_at').eq('status', 'published').order('publish_at', { ascending: false }); return <><PortalHeader title="Announcements" description="Updates shared with students and parents." />{data?.length ? <div className="grid gap-4">{data.map((item) => <article key={item.id} className="rounded-xl border border-border bg-card p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-display text-lg font-semibold">{item.title}</h2><p className="mt-1 text-xs text-muted-foreground">{formatDate(item.publish_at)}</p></div><StatusPill>{item.audience === 'specific_batch' ? 'Your batch' : item.audience}</StatusPill></div><p className="mt-4 whitespace-pre-wrap text-sm leading-6 text-muted-foreground">{item.message}</p></article>)}</div> : <EmptyState text="No announcements have been published yet." />}</> }
